### Objective
Build a production-grade User Authentication & Profile BLoC with Mocked Repository Testing in Flutter. The application demonstrates test double mocking using mocktail, stubbing asynchronous API responses, verifying call counts, and comprehensive bloc_test state machine verification covering initial state, loading transitions, authentication success, and error handling.

```dart
import 'dart:async';
import 'package:flutter/material.dart';

void main() {
  runApp(const MockingMasterclassApp());
}

class MockingMasterclassApp extends StatelessWidget {
  const MockingMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Mocking & BLoC Test Masterclass',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.indigo,
        useMaterial3: true,
      ),
      home: const MockTestHarnessScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN LAYER: USER ENTITY & REPOSITORY CONTRACT
// ─────────────────────────────────────────────────────────────────────────────

class UserProfile {
  final String id;
  final String email;
  final String displayName;

  const UserProfile({
    required this.id,
    required this.email,
    required this.displayName,
  });

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UserProfile &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          email == other.email;

  @override
  int get hashCode => id.hashCode ^ email.hashCode;
}

abstract class AuthRepository {
  Future<UserProfile> login(String email, String password);
  Future<void> logout();
}

class AuthFailure implements Exception {
  final String message;
  const AuthFailure(this.message);
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. APPLICATION LOGIC: AUTHENTICATION BLOC (Simulated)
// ─────────────────────────────────────────────────────────────────────────────

sealed class AuthState {
  const AuthState();
}

class AuthInitialState extends AuthState {
  const AuthInitialState();
}

class AuthLoadingState extends AuthState {
  const AuthLoadingState();
}

class AuthSuccessState extends AuthState {
  final UserProfile user;
  const AuthSuccessState(this.user);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AuthSuccessState && other.user == user;

  @override
  int get hashCode => user.hashCode;
}

class AuthFailureState extends AuthState {
  final String error;
  const AuthFailureState(this.error);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AuthFailureState && other.error == error;

  @override
  int get hashCode => error.hashCode;
}

class AuthManager extends ChangeNotifier {
  final AuthRepository authRepository;
  AuthState _state = const AuthInitialState();

  AuthManager({required this.authRepository});

  AuthState get state => _state;

  Future<void> login(String email, String password) async {
    _state = const AuthLoadingState();
    notifyListeners();

    try {
      final user = await authRepository.login(email, password);
      _state = AuthSuccessState(user);
    } on AuthFailure catch (e) {
      _state = AuthFailureState(e.message);
    } catch (e) {
      _state = const AuthFailureState('Unexpected system error');
    }
    notifyListeners();
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. MOCK REPOSITORY IMPLEMENTATION (Illustrating mocktail mechanics)
// ─────────────────────────────────────────────────────────────────────────────

class MockAuthRepositoryStub implements AuthRepository {
  UserProfile? Function(String email, String password)? onLogin;
  int loginCallCount = 0;
  String? lastLoginEmail;

  @override
  Future<UserProfile> login(String email, String password) async {
    loginCallCount++;
    lastLoginEmail = email;
    await Future.delayed(const Duration(milliseconds: 60)); // Simulate async latency

    if (onLogin != null) {
      final result = onLogin!(email, password);
      if (result != null) return result;
    }
    throw const AuthFailure('Invalid credentials provided.');
  }

  @override
  Future<void> logout() async {}
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. TEST HARNESS PRESENTATION SCREEN
// ─────────────────────────────────────────────────────────────────────────────

class MockTestCase {
  final String name;
  final bool passed;
  final String details;
  final int durationMs;

  const MockTestCase({
    required this.name,
    required this.passed,
    required this.details,
    required this.durationMs,
  });
}

class MockTestHarnessScreen extends StatefulWidget {
  const MockTestHarnessScreen({super.key});

  @override
  State<MockTestHarnessScreen> createState() => _MockTestHarnessScreenState();
}

class _MockTestHarnessScreenState extends State<MockTestHarnessScreen> {
  final List<MockTestCase> _cases = [];
  bool _isTesting = false;

  Future<void> _runMockTestSuite() async {
    setState(() {
      _isTesting = true;
      _cases.clear();
    });

    // TEST 1: Successful Login Flow with Mock Stubbing
    final sw1 = Stopwatch()..start();
    final mockRepo1 = MockAuthRepositoryStub();
    const testUser = UserProfile(id: 'u_101', email: 'dev@flutter.internal', displayName: 'Lead Engineer');

    // STUB: when(() => mockRepo.login('dev@flutter.internal', 'pass')).thenAnswer(testUser)
    mockRepo1.onLogin = (email, pass) => email == 'dev@flutter.internal' && pass == 'pass123' ? testUser : null;

    final manager1 = AuthManager(authRepository: mockRepo1);
    final states1 = <AuthState>[];
    manager1.addListener(() => states1.add(manager1.state));

    await manager1.login('dev@flutter.internal', 'pass123');
    sw1.stop();

    final test1Passed = states1.length == 2 &&
        states1[0] is AuthLoadingState &&
        states1[1] is AuthSuccessState &&
        (states1[1] as AuthSuccessState).user == testUser &&
        mockRepo1.loginCallCount == 1;

    _cases.add(MockTestCase(
      name: 'AuthManager: Emits [Loading, Success] and verifies repo.login called 1x',
      passed: test1Passed,
      details: 'Verified mocktail stub match and exact call verification.',
      durationMs: sw1.elapsedMilliseconds,
    ));
    setState(() {});

    // TEST 2: Failed Login Flow with Thrown AuthFailure
    final sw2 = Stopwatch()..start();
    final mockRepo2 = MockAuthRepositoryStub();
    // STUB: when(() => mockRepo.login(any, any)).thenThrow(AuthFailure)
    mockRepo2.onLogin = (email, pass) => throw const AuthFailure('User not found.');

    final manager2 = AuthManager(authRepository: mockRepo2);
    final states2 = <AuthState>[];
    manager2.addListener(() => states2.add(manager2.state));

    await manager2.login('unknown@test.com', 'wrong');
    sw2.stop();

    final test2Passed = states2.length == 2 &&
        states2[0] is AuthLoadingState &&
        states2[1] is AuthFailureState &&
        (states2[1] as AuthFailureState).error == 'User not found.';

    _cases.add(MockTestCase(
      name: 'AuthManager: Handles AuthFailure exception gracefully -> [Loading, Failure]',
      passed: test2Passed,
      details: 'Exception caught and translated into domain failure state.',
      durationMs: sw2.elapsedMilliseconds,
    ));
    setState(() {});

    // TEST 3: Verification of Uncalled Sensitive Methods (verifyNever)
    final sw3 = Stopwatch()..start();
    final mockRepo3 = MockAuthRepositoryStub();
    final manager3 = AuthManager(authRepository: mockRepo3);
    sw3.stop();

    final test3Passed = mockRepo3.loginCallCount == 0;
    _cases.add(MockTestCase(
      name: 'Security Audit: verifyNever() ensures zero interaction before user action',
      passed: test3Passed,
      details: 'Verified loginCallCount == 0 on uninitialized manager.',
      durationMs: sw3.elapsedMilliseconds,
    ));

    setState(() => _isTesting = false);
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;
    final passedCount = _cases.where((c) => c.passed).length;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Mocking & BLoC Test Verification'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children:
 [
          Card(
            elevation: 0,
            color: _cases.isNotEmpty && passedCount == _cases.length
                ? Colors.green.shade50
                : colorScheme.surfaceContainerHighest,
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
            child: Padding(
              padding: const EdgeInsets.all(18),
              child: Row(
                children: [
                  CircleAvatar(
                    radius: 24,
                    backgroundColor: _cases.isNotEmpty && passedCount == _cases.length
                        ? Colors.green
                        : colorScheme.primary,
                    child: Icon(
                      _cases.isNotEmpty && passedCount == _cases.length
                          ? Icons.verified_user_rounded
                          : Icons.hub_rounded,
                      color: Colors.white,
                    ),
                  ),
                  const SizedBox(width: 16),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          _cases.isNotEmpty && passedCount == _cases.length
                              ? 'All Mock Tests Passing ($passedCount/${_cases.length})'
                              : 'Mocktail & BLoC Test Harness',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            fontSize: 15,
                            color: _cases.isNotEmpty && passedCount == _cases.length
                                ? Colors.green.shade900
                                : colorScheme.onSurface,
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Demonstrates test doubles, stubbing with when/thenAnswer, and verification.',
                          style: TextStyle(fontSize: 12, color: colorScheme.onSurfaceVariant),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 20),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text('Mock Test Cases', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
              FilledButton.icon(
                onPressed: _isTesting ? null : _runMockTestSuite,
                icon: _isTesting
                    ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Icon(Icons.playlist_play_rounded),
                label: Text(_isTesting ? 'Verifying...' : 'Run Mock Tests'),
              ),
            ],
          ),
          const SizedBox(height: 14),
          if (_cases.isEmpty)
            Center(
              child: Padding(
                padding: const EdgeInsets.all(40.0),
                child: Text('Tap "Run Mock Tests" to execute mocked BLoC verification.', style: TextStyle(color: colorScheme.onSurfaceVariant)),
              ),
            )
          else
            ..._cases.map((c) => _buildCaseCard(c, colorScheme)),
        ],
      ),
    );
  }

  Widget _buildCaseCard(MockTestCase c, ColorScheme colorScheme) {
    return Card(
      margin: const EdgeInsets.only(bottom: 12),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      child: ListTile(
        leading: Icon(
          c.passed ? Icons.check_circle_rounded : Icons.error_rounded,
          color: c.passed ? Colors.green : Colors.red,
        ),
        title: Text(c.name, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
        subtitle: Text(c.details, style: TextStyle(fontSize: 11, color: colorScheme.onSurfaceVariant)),
        trailing: Text('${c.durationMs}ms', style: const TextStyle(fontSize: 10, fontFamily: 'monospace')),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Repository Abstraction (`AuthRepository`)**:
   Clean Architecture domain contract decoupling authentication logic from network implementations.
2. **Mocktail Double Pattern**:
   `MockAuthRepositoryStub` demonstrates how mock objects intercept method calls, capture arguments, and return pre-programmed stub responses without touching real servers.
3. **Sequential State Verification (`[Loading, Success]`)**:
   The test asserts that the state machine emits `AuthLoadingState` first, followed by `AuthSuccessState` containing the exact expected user entity.
4. **Invocation Counting (`verify().called(1)`)**:
   Verifies that `loginCallCount == 1`, proving that the BLoC did not make redundant duplicate API calls.
